public class Main{static long xsNext(long x){x^=x<<13;x^=x>>>7;x^=x<<17;return x;} static class E{int kind; long v; E l,r; E(int k,long v,E l,E r){this.kind=k;this.v=v;this.l=l;this.r=r;}} static E build(int d,long s){ s=xsNext(s); if(d==0) return new E(0,Long.remainderUnsigned(s,1000),null,null); long k=Long.remainderUnsigned(s,8); if(k<1) return new E(3,0,build(d-1,s),null); E a=build(d-1,s), b=build(d-1,xsNext(s)); return new E(k<5?1:2,0,a,b); } static long eval(E e,long p){ if(e.kind==0) return (e.v+p)%1000003; if(e.kind==1) return (eval(e.l,p)+eval(e.r,p))%1000003; if(e.kind==2) return (eval(e.l,p)*eval(e.r,p))%1000003; return (1000003-eval(e.l,p))%1000003; } static long count(E e){ return 1+(e.l!=null?count(e.l):0)+(e.r!=null?count(e.r):0); } public static void main(String[]a){ E r=build(4,12345); long total=0; for(long p=0;p<8;p++) total=(total+eval(r,p))%1000003; System.out.println(count(r)); System.out.println(total);}}